(function() {
  if (element.querySelector('.top-live-badge')) return;

  var statEl = element.querySelector('.tw-media-card-stat');
  if (!statEl) return;

  var text = statEl.textContent.trim();
  var match = text.match(/^([\d.]+)([KMB]?)\s*viewers?$/i);
  if (!match) return;

  var num = parseFloat(match[1]);
  var suffix = match[2].toUpperCase();
  if (suffix === 'K') num *= 1000;
  else if (suffix === 'M') num *= 1000000;

  var allArticles = document.querySelectorAll('article.Layout-sc-1xcs6mc-0.ghbJdj');
  var viewers = [];
  allArticles.forEach(function(card) {
    var s = card.querySelector('.tw-media-card-stat');
    if (!s) return;
    var t = s.textContent.trim();
    var m = t.match(/^([\d.]+)([KMB]?)\s*viewers?$/i);
    if (!m) return;
    var n = parseFloat(m[1]);
    var sf = m[2].toUpperCase();
    if (sf === 'K') n *= 1000;
    else if (sf === 'M') n *= 1000000;
    viewers.push({ card: card, count: n });
  });

  viewers.sort(function(a, b) { return b.count - a.count; });

  var topCount = Math.max(3, Math.ceil(viewers.length * 0.2));
  if (viewers.length > 0 && viewers.slice(0, topCount).some(function(v) { return v.card === element; })) {
    var wrapper = element.querySelector('.ScWrapper-sc-1wvuch4-0');
    if (!wrapper) return;

    var badge = document.createElement('div');
    badge.className = 'top-live-badge';
    badge.textContent = 'TOP LIVE';
    badge.style.cssText = 'position:absolute;top:8px;left:8px;background:linear-gradient(135deg,#ff4500,#ff6b35);color:#fff;font-size:11px;font-weight:700;padding:4px 10px;border-radius:4px;z-index:10;letter-spacing:0.5px;text-transform:uppercase;box-shadow:0 2px 8px rgba(255,69,0,0.5);pointer-events:none;';
    wrapper.style.position = 'relative';
    wrapper.appendChild(badge);
  }
})();

